class Buffer
{
public:
    Buffer() = default;

    explicit Buffer(std::size_t count)
        : count_(count), samples_(count ? new double[count]{} : nullptr)
    {
    }

    Buffer(const Buffer &other)
        : count_(other.count_), samples_(other.count_ ? new double[other.count_] : nullptr)
    {
        std::copy(other.samples_, other.samples_ + count_, samples_);
    }

    Buffer &operator=(const Buffer &other)
    {
        if (this == &other)
        {
            return *this;
        }

        double *newSamples = other.count_ ? new double[other.count_] : nullptr;
        std::copy(other.samples_, other.samples_ + other.count_, newSamples);

        delete[] samples_;
        samples_ = newSamples;
        count_ = other.count_;
        return *this;
    }

    ~Buffer()
    {
        delete[] samples_;
    }

private:
    std::size_t count_ = 0;
    double *samples_ = nullptr;
};

class Buffer
{
public:
    Buffer() = default;

    explicit Buffer(std::size_t count)
        : count_(count), samples_(count ? new double[count]{} : nullptr)
    {
    }

    Buffer(const Buffer &other)
        : count_(other.count_), samples_(other.count_ ? new double[other.count_] : nullptr)
    {
        std::copy(other.samples_, other.samples_ + count_, samples_);
    }

    Buffer(Buffer &&other) noexcept
        : count_(other.count_), samples_(other.samples_)
    {
        other.count_ = 0;
        other.samples_ = nullptr;
    }

    Buffer &operator=(Buffer other) noexcept
    {
        std::swap(count_, other.count_);
        std::swap(samples_, other.samples_);
        return *this;
    }

    ~Buffer()
    {
        delete[] samples_;
    }

private:
    std::size_t count_ = 0;
    double *samples_ = nullptr;
};

