class Callback
{
public:
    template<typename F>
    Callback(F fn)
        : self_(std::make_shared<Model<F>>(std::move(fn)))
    {
    }

    void operator()(int value) const
    {
        self_->Call(value);
    }

private:
    struct Concept
    {
        virtual ~Concept() = default;
        virtual void Call(int value) const = 0;
    };

    template<typename F>
    struct Model final : Concept
    {
        explicit Model(F fn) : fn_(std::move(fn)) {}
        void Call(int value) const override { fn_(value); }
        F fn_;
    };

    std::shared_ptr<const Concept> self_;
};

