public:
    template<typename F>
    FunctionRef(F &fn) noexcept
        : object_(static_cast<void *>(&fn))
        , callback_([](void *object, Args... args) -> R
        {
            return (*static_cast<F *>(object))(std::forward<Args>(args)...);
        })
    {
