template<typename T, std::size_t N>
class SpscRing
{
public:
    bool Push(const T &value)
    {
        const std::size_t head = head_.load(std::memory_order_relaxed);
        const std::size_t next = (head + 1) % N;
        if (next == tail_.load(std::memory_order_acquire))
        {
            return false;
        }

        buffer_[head] = value;
        head_.store(next, std::memory_order_release);
        return true;
    }

    std::optional<T> Pop()
    {
        const std::size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail == head_.load(std::memory_order_acquire))
        {
            return std::nullopt;
        }

        T value = buffer_[tail];
        tail_.store((tail + 1) % N, std::memory_order_release);
        return value;
    }

private:
    std::array<T, N> buffer_{};
    std::atomic<std::size_t> head_{0};
    std::atomic<std::size_t> tail_{0};
};

#include <atomic>
#include <cstdint>

struct Node
{
    Node *next = nullptr;
};

struct TaggedPtr
{
    Node *ptr = nullptr;
    std::uint32_t tag = 0;
};

std::atomic<TaggedPtr> head;

bool TryPush(Node *node)
{
    TaggedPtr expected = head.load(std::memory_order_acquire);
    TaggedPtr desired{};

    do
    {
        node->next = expected.ptr;
        desired.ptr = node;
        desired.tag = expected.tag + 1;
    }
    while (!head.compare_exchange_weak(expected,
                                       desired,
                                       std::memory_order_release,
                                       std::memory_order_acquire));

    return true;
}

