struct Node
{
    Node *next = nullptr;
};

struct TaggedPtr
{
    Node *ptr = nullptr;
    std::uint32_t tag = 0;
};

constexpr int MaxThreads = 8;
std::atomic<TaggedPtr> head;

struct HazardSlot
{
    std::atomic<void *> protectedPtr{nullptr};
};

HazardSlot g_hazardSlots[MaxThreads];

Node *AcquireProtectedHead(HazardSlot &slot)
{
    Node *candidate = nullptr;
    do
    {
        candidate = head.load(std::memory_order_acquire).ptr;
        slot.protectedPtr.store(candidate, std::memory_order_release);
    }
    while (candidate != head.load(std::memory_order_acquire).ptr);

    return candidate;
}

void ReleaseHazard(HazardSlot &slot)
{
    slot.protectedPtr.store(nullptr, std::memory_order_release);
}

