enum class ParseState
{
    WaitStart,
    WaitLength,
    WaitPayload,
    WaitChecksum
};

struct Parser
{
    ParseState state = ParseState::WaitStart;
    std::uint8_t length = 0;
    std::vector<std::uint8_t> payload;

    bool Consume(std::uint8_t byte)
    {
        switch (state)
        {
        case ParseState::WaitStart:
            if (byte == 0xAA)
            {
                payload.clear();
                state = ParseState::WaitLength;
            }
            break;
        case ParseState::WaitLength:
            length = byte;
            state = ParseState::WaitPayload;
            break;
        case ParseState::WaitPayload:
            payload.push_back(byte);
            if (payload.size() == length)
            {
                state = ParseState::WaitChecksum;
            }
            break;
        case ParseState::WaitChecksum:
            state = ParseState::WaitStart;
            return true;
        }
        return false;
    }
};

