class Signal
{
public:
    using Callback = std::function<void(int)>;

    void Connect(Callback callback)
    {
        callbacks_.push_back(std::move(callback));
    }

    void Emit(int value)
    {
        for (const auto &callback : callbacks_) callback(value);
    }

private:
    std::vector<Callback> callbacks_;
};

