#pragma pack(push, 1)
struct FrameHeader
{
    std::uint16_t magic;
    std::uint16_t payloadSize;
    std::uint8_t command;
    std::uint8_t sequence;
};
#pragma pack(pop)

/* Wire format:
   [FrameHeader][payload bytes][CRC16]
*/

#include <cstddef>
#include <cstdint>
#include <span>

std::uint16_t Crc16Modbus(std::span<const std::uint8_t> bytes)
{
    std::uint16_t crc = 0xFFFF;
    for (std::uint8_t byte : bytes)
    {
        crc ^= byte;
        for (int bit = 0; bit < 8; ++bit)
        {
            crc = (crc & 1) ? static_cast<std::uint16_t>((crc >> 1) ^ 0xA001)
                            : static_cast<std::uint16_t>(crc >> 1);
        }
    }
    return crc;
}

std::vector<std::uint8_t> rxBuffer;

void ConsumeBytes(const std::uint8_t *data, std::size_t count)
{
    rxBuffer.insert(rxBuffer.end(), data, data + count);

    while (HasCompleteFrame(rxBuffer))
    {
        Frame frame = ExtractNextFrame(rxBuffer);
        HandleFrame(frame);
    }
}

