def frame_signal(values: np.ndarray, frame_size: int, hop_size: int) -> np.ndarray:
    frames = []
    for start in range(0, values.size - frame_size + 1, hop_size):
        frames.append(values[start:start + frame_size])
    return np.stack(frames, axis=0)

