from collections.abc import Callable

Step = tuple[str, Callable[[], bool]]

def run_sequence(steps: list[Step]) -> list[tuple[str, bool]]:
    results: list[tuple[str, bool]] = []
    for name, step in steps:
        passed = step()
        results.append((name, passed))
        if not passed:
            break
    return results

