#include <Wire.h>

uint8_t ReadRegister(uint8_t address, uint8_t reg)
{
    Wire.beginTransmission(address);
    Wire.write(reg);
    Wire.endTransmission(false);
    Wire.requestFrom((int)address, 1);
    return Wire.available() ? Wire.read() : 0;
}

#include <SPI.h>
const int CS_PIN = 10;

uint8_t ReadSpiRegister(uint8_t reg)
{
    digitalWrite(CS_PIN, LOW);
    SPI.transfer(reg | 0x80);
    uint8_t value = SPI.transfer(0x00);
    digitalWrite(CS_PIN, HIGH);
    return value;
}

class LedBlinker
{
public:
    explicit LedBlinker(int pin) : pin_(pin), lastToggle_(0), state_(false) {}

    void begin()
    {
        pinMode(pin_, OUTPUT);
    }

    void update(unsigned long nowMs)
    {
        if (nowMs - lastToggle_ >= 200)
        {
            lastToggle_ = nowMs;
            state_ = !state_;
            digitalWrite(pin_, state_ ? HIGH : LOW);
        }
    }

private:
    int pin_;
    unsigned long lastToggle_;
    bool state_;
};

enum class RobotState
{
    Idle,
    Search,
    Follow,
    Action
};

RobotState state = RobotState::Idle;

void loop()
{
    switch (state)
    {
        case RobotState::Idle:   if (StartRequested()) state = RobotState::Search; break;
        case RobotState::Search: if (TargetFound()) state = RobotState::Follow;    break;
        case RobotState::Follow: if (CloseEnough()) state = RobotState::Action;    break;
        case RobotState::Action: DoAction(); state = RobotState::Search;           break;
    }
}

