enum class RxState { WaitStx, ReadCommand, ReadLength, ReadPayload, ReadChecksum };
RxState state = RxState::WaitStx;
std::vector<unsigned char> payload;

void OnByte(unsigned char byte)
{
    switch (state)
    {
        case RxState::WaitStx: if (byte == 0x02) state = RxState::ReadCommand; break;
        case RxState::ReadCommand: state = RxState::ReadLength; break;
        case RxState::ReadLength: payload.clear(); expectedLength = byte; state = expectedLength ? RxState::ReadPayload : RxState::ReadChecksum; break;
        case RxState::ReadPayload: payload.push_back(byte); if (payload.size() >= expectedLength) state = RxState::ReadChecksum; break;
        case RxState::ReadChecksum: HandleFrame(payload); state = RxState::WaitStx; break;
    }
}

uint16_t crc = 0xFFFF;
for (unsigned char byte : payload)
{
    crc ^= byte;
    for (int i = 0; i < 8; ++i)
    {
        crc = (crc & 1) ? ((crc >> 1) ^ 0xA001) : (crc >> 1);
    }
}
frame.push_back(static_cast<unsigned char>(crc & 0xFF));
frame.push_back(static_cast<unsigned char>((crc >> 8) & 0xFF));

